CREATE TABLE public.patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.patients TO authenticated;
GRANT ALL ON public.patients TO service_role;
ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.leads ADD COLUMN patient_id uuid REFERENCES public.patients(id), ADD COLUMN work_area text CHECK (work_area IN ('agents','business','callcenter','target')), ADD COLUMN business_segment text CHECK (business_segment IN ('B2B','B2C')), ADD COLUMN clinical_direction text, ADD COLUMN campaign text;
CREATE FUNCTION public.patient_phone_key(raw text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN length(d)=10 AND left(d,1)='0' THEN '+996'||substring(d from 2) WHEN length(d)=9 THEN '+996'||d WHEN length(d)=12 AND left(d,3)='996' THEN '+'||d ELSE '+'||d END FROM (SELECT regexp_replace(raw,'[^0-9]','','g') d) s $$;
INSERT INTO public.patients(phone) SELECT DISTINCT public.patient_phone_key(phone) FROM public.leads;
UPDATE public.leads l SET patient_id=p.id FROM public.patients p WHERE p.phone=public.patient_phone_key(l.phone);
ALTER TABLE public.leads ALTER COLUMN patient_id SET NOT NULL;
CREATE INDEX leads_patient_id_idx ON public.leads(patient_id);
CREATE POLICY "patient identity via visible encounter" ON public.patients FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.leads l WHERE l.patient_id=patients.id AND public.can_see_branch(l.branch_code)));
CREATE FUNCTION public.assign_patient_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE key text; pid uuid; BEGIN key:=public.patient_phone_key(NEW.phone); INSERT INTO public.patients(phone) VALUES(key) ON CONFLICT(phone) DO UPDATE SET phone=excluded.phone RETURNING id INTO pid; NEW.patient_id:=pid; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_patient_identity() FROM PUBLIC;
CREATE TRIGGER assign_patient_identity BEFORE INSERT OR UPDATE OF phone,patient_id ON public.leads FOR EACH ROW EXECUTE FUNCTION public.assign_patient_identity();
DROP POLICY "leads insert" ON public.leads;
CREATE POLICY "leads insert" ON public.leads FOR INSERT TO authenticated WITH CHECK (public.is_staff() AND public.can_see_branch(branch_code));
DROP POLICY "leads update" ON public.leads;
CREATE POLICY "leads update" ON public.leads FOR UPDATE TO authenticated USING (public.is_staff() AND public.can_see_branch(branch_code)) WITH CHECK (public.is_staff() AND public.can_see_branch(branch_code));
CREATE TABLE public.employee_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads(id), reason text NOT NULL CHECK(length(trim(reason))>0), confirmed_by text NOT NULL DEFAULT public.my_email(), confirmed_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolved_by text, resolution text);
GRANT SELECT, INSERT, UPDATE ON public.employee_errors TO authenticated;
GRANT ALL ON public.employee_errors TO service_role;
ALTER TABLE public.employee_errors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "leaders read errors" ON public.employee_errors FOR SELECT TO authenticated USING (public.is_admin() AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND public.can_see_branch(l.branch_code)));
CREATE POLICY "leaders confirm errors" ON public.employee_errors FOR INSERT TO authenticated WITH CHECK (public.is_admin() AND confirmed_by=public.my_email() AND resolved_at IS NULL AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND public.can_see_branch(l.branch_code)));
CREATE POLICY "leaders resolve errors" ON public.employee_errors FOR UPDATE TO authenticated USING (public.is_admin()) WITH CHECK(public.is_admin() AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND public.can_see_branch(l.branch_code)));
CREATE FUNCTION public.error_audit_stamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.confirmed_by:=public.my_email(); NEW.confirmed_at:=now(); NEW.resolved_at:=NULL; NEW.resolved_by:=NULL; ELSE NEW.lead_id:=OLD.lead_id; NEW.reason:=OLD.reason; NEW.confirmed_by:=OLD.confirmed_by; NEW.confirmed_at:=OLD.confirmed_at; IF OLD.resolved_at IS NOT NULL THEN RAISE EXCEPTION 'Already resolved'; END IF; IF length(trim(coalesce(NEW.resolution,'')))=0 THEN RAISE EXCEPTION 'Resolution required'; END IF; NEW.resolved_at:=now(); NEW.resolved_by:=public.my_email(); END IF; RETURN NEW; END $$;
CREATE TRIGGER employee_error_audit BEFORE INSERT OR UPDATE ON public.employee_errors FOR EACH ROW EXECUTE FUNCTION public.error_audit_stamp();